import React from 'react';
import { Helmet } from 'react-helmet-async';
import { LINM_FAVICON, LINM_ICON_192, LINM_OG_IMAGE } from '../../constants/linmBrand';
import { SEO_OG } from '../../constants/seoKeywords';
import { SEO_BRAND_TITLE, absoluteUrl } from '../../constants/seoSite';

export interface SeoHeadProps {
  title: string;
  description: string;
  path: string;
  ogType?: 'website' | 'article';
  noindex?: boolean;
  jsonLd?: Record<string, unknown> | Record<string, unknown>[];
}

export const SeoHead: React.FC<SeoHeadProps> = ({
  title,
  description,
  path,
  ogType = 'website',
  noindex = false,
  jsonLd,
}) => {
  const canonical = absoluteUrl(path);
  const fullTitle = title.includes(SEO_BRAND_TITLE) ? title : `${title} · ${SEO_BRAND_TITLE}`;
  const ogImage = absoluteUrl(LINM_OG_IMAGE);
  const favicon = absoluteUrl(LINM_FAVICON);
  const appleTouch = absoluteUrl(LINM_ICON_192);

  return (
    <Helmet>
      <html lang="vi" />
      <title>{fullTitle}</title>
      <meta name="description" content={description} />
      <link rel="icon" href={favicon} type="image/png" sizes="192x192" />
      <link rel="apple-touch-icon" href={appleTouch} />
      <link rel="canonical" href={canonical} />
      {noindex ? (
        <meta name="robots" content="noindex, nofollow" />
      ) : (
        <meta name="robots" content="index, follow" />
      )}
      <meta property="og:type" content={ogType} />
      <meta property="og:locale" content="vi_VN" />
      <meta property="og:site_name" content={SEO_OG.siteName} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={canonical} />
      <meta property="og:image" content={ogImage} />
      <meta property="og:image:width" content={String(SEO_OG.imageWidth)} />
      <meta property="og:image:height" content={String(SEO_OG.imageHeight)} />
      <meta property="og:image:alt" content={SEO_OG.imageAlt} />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={ogImage} />
      <meta name="twitter:image:alt" content={SEO_OG.imageAlt} />
      {jsonLd && (
        <script type="application/ld+json">
          {JSON.stringify(jsonLd)}
        </script>
      )}
    </Helmet>
  );
};
